api_signature:
from typing import Protocol
from dataclasses import dataclass

@dataclass(frozen=True)
class ToggleContext:
    principal_id: str | None
    tenant_id: str | None
    environment: str

class FeatureToggle(Protocol):
    key: str
    def is_active(self, ctx: ToggleContext) -> bool: ...

consumption_example:
class HotFeature:
    key = 'hot_feature'
    def is_active(self, ctx: ToggleContext) -> bool:
        return ctx.environment == 'prod' and ctx.tenant_id == 'acme'

ft: FeatureToggle = HotFeature()
assert ft.key == 'hot_feature'
